1: #!/usr/bin/env node
2: /**
3:  * CLI runner for Light Novel to Markdown (.md) Translator
4:  *
5:  * Usage:
6:  *   npx tsx src/cli/ln-translator.ts <path-to-pdf> [options]
7:  *
8:  * Options:
9:  *   --pages <range>     e.g. 1-10 or 1,2,5 or all (default: all)
10:  *   --out <path>        Output markdown file path
11:  *   --model <model>     LLM Model ID (e.g. gpt-4o-mini, gemini-1.5-flash)
12:  *   --provider <name>   LLM Provider (openai, google, anthropic, etc.)
13:  *   --token <key>       API key/token
14:  *   --base-url <url>    Custom base URL
15:  */
16: import fs from 'node:fs';
17: import path from 'node:path';
18: import os from 'node:os';
19: import { runLNTranslation } from '../main/pipeline/ln-translator';
20: import { AppSettings, DEFAULT_SETTINGS } from '../main/pipeline/types';
21: 
22: function getAppSettings(): AppSettings {
23:   const appData = process.env.APPDATA || (process.platform === 'darwin' ? path.join(os.homedir(), 'Library/Application Support') : path.join(os.homedir(), '.config'));
24:   const settingsPath = path.join(appData, 'pdf2zh-app', 'pdf2zh-settings.json');
25: 
26:   if (fs.existsSync(settingsPath)) {
27:     try {
28:       const data = fs.readFileSync(settingsPath, 'utf-8');
29:       return { ...DEFAULT_SETTINGS, ...JSON.parse(data) };
30:     } catch {
31:       // ignore
32:     }
33:   }
34:   return { ...DEFAULT_SETTINGS };
35: }
36: 
37: function parsePageRange(rangeStr: string): number[] {
38:   const pages: Set<number> = new Set();
39:   const parts = rangeStr.split(',');
40:   for (const part of parts) {
41:     const trimmed = part.trim();
42:     if (trimmed.includes('-')) {
43:       const [startStr, endStr] = trimmed.split('-');
44:       const start = parseInt(startStr, 10);
45:       const end = parseInt(endStr, 10);
46:       if (!isNaN(start) && !isNaN(end)) {
47:         for (let i = start; i <= end; i++) {
48:           pages.add(i);
49:         }
50:       }
51:     } else {
52:       const p = parseInt(trimmed, 10);
53:       if (!isNaN(p)) {
54:         pages.add(p);
55:       }
56:     }
57:   }
58:   return Array.from(pages).sort((a, b) => a - b);
59: }
60: 
61: async function main() {
62:   const args = process.argv.slice(2);
63: 
64:   if (args.length === 0 || args.includes('--help') || args.includes('-h')) {
65:     console.log(`
66: Light Novel to Markdown (.md) Translator CLI
67: --------------------------------------------
68: Usage:
69:   npx tsx src/cli/ln-translator.ts <path-to-pdf> [options]
70: 
71: Arguments:
72:   <path-to-pdf>       Path to the Light Novel PDF file
73: 
74: Options:
75:   --pages <range>     Page range to translate, e.g. "1-20" or "1,3,5" (default: all)
76:   --out <path>        Output markdown file path (default: <pdf_name>_translated.md)
77:   --concurrency <n>   Number of concurrent LLM workers (default: 4)
78:   --chunk-size <n>    Number of pages per chunk (default: 3)
79:   --provider <name>   LLM Provider (default from settings or 'openai')
80:   --model <model>     LLM Model ID (default from settings or 'gpt-4o-mini')
81:   --token <key>       API Token (default from settings or OPENAI_API_KEY env)
82:   --base-url <url>    Custom Base URL (optional)
83: 
84: Examples:
85:   npx tsx src/cli/ln-translator.ts "novel.pdf" --pages 1-15
86:   npx tsx src/cli/ln-translator.ts "novel.pdf" --model "gpt-4o" --token "sk-..."
87: `);
88:     process.exit(0);
89:   }
90: 
91:   const pdfPath = path.resolve(args[0]);
92:   if (!fs.existsSync(pdfPath)) {
93:     console.error(`[Error] File not found: ${pdfPath}`);
94:     process.exit(1);
95:   }
96: 
97:   const settings = getAppSettings();
98: 
99:   // Parse command line flags
100:   let selectedPages: number[] | undefined;
101:   let outputPath: string | undefined;
102:   let concurrency = 4;
103:   let chunkPageSize = 3;
104: 
105:   for (let i = 1; i < args.length; i++) {
106:     const arg = args[i];
107:     if (arg === '--pages' && args[i + 1]) {
108:       selectedPages = parsePageRange(args[++i]);
109:     } else if (arg === '--out' && args[i + 1]) {
110:       outputPath = path.resolve(args[++i]);
111:     } else if (arg === '--concurrency' && args[i + 1]) {
112:       concurrency = parseInt(args[++i], 10) || 4;
113:     } else if (arg === '--chunk-size' && args[i + 1]) {
114:       chunkPageSize = parseInt(args[++i], 10) || 3;
115:     } else if (arg === '--provider' && args[i + 1]) {
116:       settings.llmProvider = args[++i];
117:     } else if (arg === '--model' && args[i + 1]) {
118:       settings.llmModel = args[++i];
119:     } else if (arg === '--token' && args[i + 1]) {
120:       settings.llmApiToken = args[++i];
121:     } else if (arg === '--base-url' && args[i + 1]) {
122:       settings.llmBaseUrl = args[++i];
123:     }
124:   }
125: 
126:   // Fallback to environment variables if token not in settings
127:   if (!settings.llmApiToken) {
128:     settings.llmApiToken = process.env.OPENAI_API_KEY || process.env.GEMINI_API_KEY || process.env.ANTHROPIC_API_KEY || '';
129:   }
130: 
131:   console.log(`Starting LN Translator CLI...`);
132:   console.log(`Using settings: Provider=${settings.llmProvider}, Model=${settings.llmModel}`);
133: 
134:   const abortSignal = { aborted: false };
135:   process.on('SIGINT', () => {
136:     console.log(`\nCancellation requested... wrapping up.`);
137:     abortSignal.aborted = true;
138:   });
139: 
140:   try {
141:     const result = await runLNTranslation({
142:       inputPath: pdfPath,
143:       outputPath,
144:       settings,
145:       selectedPages,
146:       concurrency,
147:       chunkPageSize,
148:       abortSignal,
149:     });
