1: /**
2:  * Light Novel to Markdown (.md) Translator Pipeline
3:  *
4:  * Features:
5:  * - Two-Pass Architecture:
6:  *   Pass 1: Preliminary scan of ALL pages to build global novel context,
7:  *           detect all chapters/bab, detect characters, and identify/filter
8:  *           repetitive running headers, footers & "Volume 1" spam in early pages.
9:  *   Pass 2: Chunking mode with concurrent worker pool for fast translation
10:  *           of hundreds of pages.
11:  * - Speaker identification on dialogues: `Nama: "..."`
12:  * - Clean chapter headings (`# Bab ...`) and page markers (`--- \n*Halaman X*\n`).
13:  * - Real-time verbose console logging.
14:  */
15: import fs from 'node:fs';
16: import path from 'node:path';
17: import { AppSettings, ProgressEvent } from './types';
