const fs = require('fs');
const readline = require('readline');

async function scan() {
  const fileStream = fs.createReadStream('D:/JV/[Ruidrive] Rokudenashi Majutsu Koushi to Akashic Records/[Ruidrive] Rokudenashi Majutsu Koushi to Akashic Records/[Ruidrive] Rokudenashi Majutsu Koushi to Akashic Records - Volume 01/Rokudenashi Majutsu Koushi to Akashic Records - Volume 01-24.txt');
  const rl = readline.createInterface({ input: fileStream, crlfDelay: Infinity });

  let lineNo = 0;
  let currentVol = 0;
  const structure = [];

  for await (const line of rl) {
    lineNo++;
    const vMatch = line.match(/^ROKUDENASHI MAJUTSU KOUSHI TO AKASHIC RECORDS - VOLUME (\d+)/i);
    if (vMatch) {
      currentVol = parseInt(vMatch[1], 10);
      structure.push({ type: 'VOL', vol: currentVol, line: lineNo, text: line.trim() });
      continue;
    }

    const trimmed = line.trim();
    if (/^(Prolog|Prologue|Epilog|Epilogue|Bab \d+|Chapter \d+|Kata Penutup|Afterword)/i.test(trimmed)) {
      structure.push({ type: 'CHAP', vol: currentVol, line: lineNo, text: trimmed });
    }
  }

  console.log('Total headings found:', structure.length);
  console.log(structure.slice(0, 25));
}

scan();
"

