        res.on('end', () => resolve({ idx: i, status: res.statusCode, len: d.length }));
      });
      req.on('error', reject);
      req.write(payload);
      req.end();
    });
  });

  const results = await Promise.all(promises);
  console.log('Done in', ((Date.now() - start)/1000).toFixed(1), 's', results);
}

