  console.log('\n✅ Pengaturan berhasil disimpan ke config.json!');
}

async function parseAllVolumesAndChapters(filePath) {
  if (!fs.existsSync(filePath)) {
    throw new Error(`File sumber tidak ditemukan di: ${path.resolve(filePath)}`);
  }

  const fileStream = fs.createReadStream(filePath, { encoding: 'utf-8' });
  const rl = readline.createInterface({ input: fileStream, crlfDelay: Infinity });

  const chapters = [];
  let currentVol = 1;
  let currentChapter = null;
  let inTocOrDisclaimer = true;

  for await (const rawLine of rl) {
    const line = rawLine.trim();

    // Deteksi Volume
    const volMatch = rawLine.match(/^ROKUDENASHI MAJUTSU KOUSHI TO AKASHIC RECORDS - VOLUME (\d+)/i);
    if (volMatch) {
      currentVol = parseInt(volMatch[1], 10);
      inTocOrDisclaimer = true;
      continue;
    }

    // Bersihkan sampah watermark
    if (!line) continue;
    if (/^ruidrive\.com$/i.test(line)) continue;
    if (/^Volume \d+$/i.test(line)) continue;
    if (/^QWER - image\d+\./i.test(line)) continue;
    if (/^PDF by:/i.test(line)) continue;

    // Deteksi Bab / Prolog / Epilog
    const isHeading = /^(Prolog|Prologue|Epilog|Epilogue|Bab \d+|Chapter \d+|Kata Penutup|Afterword)/i.test(line);

    if (isHeading) {
      if (rawLine.includes('') || line.length < 3) continue;

      inTocOrDisclaimer = false;

      if (currentChapter && currentChapter.lines.length > 0) {
        chapters.push(currentChapter);
      }

      const chapterIndex = chapters.filter(c => c.volNum === currentVol).length + 1;
      const chId = `vol${String(currentVol).padStart(2, '0')}_ch${String(chapterIndex).padStart(2, '0')}`;

      currentChapter = {
        id: chId,
        volNum: currentVol,
        title: line,
        lines: []
      };
      continue;
    }

    if (inTocOrDisclaimer) continue;

    if (currentChapter) {
      currentChapter.lines.push(line);
    }
  }

  if (currentChapter && currentChapter.lines.length > 0) {
    chapters.push(currentChapter);
  }

  return chapters;
}

// Potong per paragraf/adegan dengan membawa tail overlap (konteks adegan sebelumnya)
function splitIntoParagraphSafeChunks(lines, maxChars) {
  const chunks = [];
  let currentLines = [];
  let currentLength = 0;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    currentLines.push(line);
    currentLength += line.length + 1;

    // Potong jika melebihi ukuran target dan berada pada akhir kalimat atau jeda dialog
    const isGoodBreakPoint = /[.!?…”"]$/.test(line) || line === '';

    if (currentLength >= maxChars && isGoodBreakPoint) {
      chunks.push(currentLines.join('\n'));
      currentLines = [];
      currentLength = 0;
    }
  }

  if (currentLines.length > 0) {
    chunks.push(currentLines.join('\n'));
  }

  return chunks;
}

// Memanggil API LLM dengan proteksi retry otomatis
async function callLLM(promptText, previousContext, cfg, retryCount = 3) {
  let userContent = '';
  if (previousContext) {
    userContent = `[KONTEKS KEJADIAN DARI CHUNK SEBELUMNYA (JANGAN DITERJEMAHKAN ULANG, HANYA ACUAN HUBUNGAN CERITA)]:
"...${previousContext.slice(-350)}..."

[LANJUTAN CERITA YANG HARUS DITERJEMAHKAN]:
${promptText}`;
  } else {
    userContent = `[MULAI BAB/ADEGAN]:
${promptText}`;
  }

  const payload = JSON.stringify({
    model: cfg.model,
    messages: [
      { role: 'system', content: SYSTEM_PROMPT },
      { role: 'user', content: userContent }
    ],
    temperature: 0.7,
    stream: false
  });

  for (let attempt = 1; attempt <= retryCount; attempt++) {
    try {
      const response = await fetch(cfg.apiUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${cfg.apiKey}`
        },
        body: payload
      });

      if (!response.ok) {
        const errorText = await response.text();
        throw new Error(`HTTP ${response.status}: ${errorText}`);
      }

      const json = await response.json();
      const content = json.choices?.[0]?.message?.content;
      if (!content || !content.trim()) {
        throw new Error('LLM mengembalikan output kosong');
      }

      return content.trim();
    } catch (err) {
      console.warn(`\n⚠️  [Percobaan ${attempt}/${retryCount}] Gagal: ${err.message}`);
      if (attempt === retryCount) throw err;
      await new Promise(r => setTimeout(r, 2000 * attempt));
    }
  }

  throw new Error('Gagal menghubungi API setelah beberapa kali percobaan.');
}

// Concurrency runner yang menjaga indeks urutan tetap presisi
async function mapConcurrent(items, limit, fn) {
  const results = new Array(items.length);
  let nextIdx = 0;

  async function worker() {
    while (nextIdx < items.length) {
      const current = nextIdx++;
      results[current] = await fn(items[current], current);
    }
  }

  const workers = Array.from({ length: Math.min(limit, items.length) }, () => worker());
  await Promise.all(workers);
  return results;
}

async function startTranslation(cfg) {
  console.log('\n======================================================');
  console.log('🚀 MEMULAI PROSES TRANSLASI BATCH (TERMUX ENGINE)');
  console.log('======================================================');
  console.log(`📁 Input  : ${cfg.inputFile}`);
  console.log(`📄 Output : ${cfg.outputFile}`);
  console.log(`🤖 Model  : ${cfg.model} via ${new URL(cfg.apiUrl).hostname}`);
  console.log(`⚡ Worker : ${cfg.concurrency} worker paralel`);
  console.log('======================================================\n');

  console.log('🔍 Membaca dan memetakan struktur bab...');
  const chapters = await parseAllVolumesAndChapters(cfg.inputFile);
  console.log(`✅ Terdeteksi ${chapters.length} Bab dari seluruh Volume.\n`);

  const checkpoint = loadCheckpoint();
  checkpoint.totalChapters = chapters.length;

  let lastVol = 0;

  for (let i = 0; i < chapters.length; i++) {
    const ch = chapters[i];

    if (checkpoint.completedIds.includes(ch.id)) {
      console.log(`⏭️  [${i + 1}/${chapters.length}] Lewati ${ch.id} (${ch.title}) - Sudah selesai.`);
      lastVol = ch.volNum;
      continue;
    }

    console.log(`\n------------------------------------------------------`);
    console.log(`📖 [${i + 1}/${chapters.length}] Memproses: Volume ${ch.volNum} - ${ch.title} (${ch.lines.length} baris)`);
    console.log(`------------------------------------------------------`);

    let volumeHeader = '';
    if (ch.volNum !== lastVol) {
      volumeHeader = `\n\n${'='.repeat(80)}\nROKUDENASHI MAJUTSU KOUSHI TO AKASHIC RECORDS - VOLUME ${String(ch.volNum).padStart(2, '0')}\n${'='.repeat(80)}\n\n`;
      lastVol = ch.volNum;
    }

    const chunks = splitIntoParagraphSafeChunks(ch.lines, cfg.maxChunkChars);
    console.log(`📦 Dibagi menjadi ${chunks.length} bagian adegan.`);

    const startTime = Date.now();
    const translatedChunks = await mapConcurrent(chunks, cfg.concurrency, async (chunkText, idx) => {
      const prevContext = idx > 0 ? chunks[idx - 1] : null;
      const cStart = Date.now();
      const res = await callLLM(chunkText, prevContext, cfg);
      const cDuration = ((Date.now() - cStart) / 1000).toFixed(1);
      console.log(`   ⚡ Bagian [${idx + 1}/${chunks.length}] selesai (${cDuration}s)`);
      return res;
    });

    const totalDuration = ((Date.now() - startTime) / 1000).toFixed(1);
    console.log(`✅ Bab selesai dalam ${totalDuration}s`);

    const translatedChapterText = translatedChunks.join('\n\n');
    const chapterOutput = `${volumeHeader}### [VOLUME ${String(ch.volNum).padStart(2, '0')}] ${ch.title}\n\n${translatedChapterText}\n\n`;

    fs.appendFileSync(cfg.outputFile, chapterOutput, 'utf-8');

    checkpoint.lastCompletedId = ch.id;
    checkpoint.completedIds.push(ch.id);
    saveCheckpoint(checkpoint);

    console.log(`💾 Bab ${ch.id} berhasil disimpan ke ${cfg.outputFile}`);
  }

  console.log('\n======================================================');
  console.log('🎉 SELURUH VOLUME (VOL 01 - 24) TELAH SELESAI!');
  console.log(`📁 File hasil akhir: ${cfg.outputFile}`);
  console.log('======================================================\n');
}

async function main() {
  const cfg = loadConfig();

  // Cek argumen command line
  const args = process.argv.slice(2);
  if (args.includes('--setup') || !cfg.apiKey) {
    if (!cfg.apiKey) {
      console.log('⚠️  API Key belum ditemukan! Menjalankan setup interaktif pertama kali...');
    }
    await runInteractiveSetup(cfg);
  }

  console.log('\nPilihan Menu:');
  console.log('1. Mulai Terjemahkan (Lanjut / Start)');
  console.log('2. Ubah Pengaturan (Setup Config)');
  console.log('3. Keluar');

  const choice = await askQuestion('\nPilih menu (1/2/3) [1]: ');

  if (choice === '2') {
    await runInteractiveSetup(cfg);
    await main();
  } else if (choice === '3') {
    process.exit(0);
  } else {
    if (!cfg.apiKey) {
      console.error('❌ Error: API Key wajib diisi!');
      process.exit(1);
    }
    await startTranslation(cfg);
  }
}

main().catch(err => {
  console.error('\n❌ Terjadi kesalahan fatal:', err.message);
  process.exit(1);
});

