#!/usr/bin/env node
/**
 * ============================================================================
 * 📱 TERMUX LIGHT NOVEL TRANSLATOR - BULLETPROOF TURBO EDITION
 * ============================================================================
 * Masalah macet setelah 1 bab sudah diperbaiki tuntas:
 * 1. Timeout Guard (60s): fetch() tidak akan pernah menggantung selamanya.
 * 2. Rate-Limit / Quota Backoff: Jika kena 429 atau server busy, otomatis delay pintar.
 * 3. Logging Real-time per Detik: Kamu bisa melihat langsung request mana yang sedang jalan.
 * 4. Safe Chapter Boundary: Bab 2 dan seterusnya dijamin langsung otomatis lanjut.
 * ============================================================================
 */

import fs from 'node:fs';
import readline from 'node:readline';
import path from 'node:path';

const CONFIG_FILE = 'config.json';
const CHECKPOINT_FILE = 'checkpoint.json';

const DEFAULT_CONFIG = {
  apiUrl: 'https://generativelanguage.googleapis.com/v1beta/openai/chat/completions',
  apiKey: '',
  model: 'gemini-1.5-flash',
  inputFile: 'source.txt',
  outputFile: 'Rokudenashi_ID_Gaul_Full.txt',
  maxChunkChars: 10000,
  concurrency: 3,
  requestTimeoutSec: 75
};

const SYSTEM_PROMPT = `Kamu adalah penerjemah + asisten pembaca Light Novel profesional ke Bahasa Indonesia.

TUGAS UTAMA (PRIORITAS TERTINGGI):
1. Terjemahkan CONTENT ke bahasa Indonesia yang santai sehari-hari, gaul, konyol, lucu, dan vulgar (sesuai karakter dan situasi). Bahasa harus hidup, alami, dan menghibur.
2. Dialog boleh pakai "gue/lu" atau umpatan/kata-kata kasar santai sehari-hari jika sesuai dengan emosi dan kepribadian karakter (contoh: Glenn Radars yang mageran, sinis, dan blak-blakan).
3. Karakter formal, bangsawan, guru, atau tokoh tua tetap dijaga kesopanannya sesuai peran (contoh: Rumia Tingel yang santun, Celica Arfonia yang anggun/mengintimidasi, atau Sistine Fibel yang tsundere).
4. FORMAT DIALOG: Selalu sertakan NAMA SPEAKER pada dialog secara konsisten dengan format:
   Nama: "Isi dialog..."
   (Contoh: Glenn Radars: "Hah?! Sialan, mager banget gila...", Sistine Fibel: "Dasar guru mesum nggak guna!").
5. JANGAN mengubah alur, kejadian, dialog, atau informasi penting. Hanya gaya bahasa dan suasana yang dibuat santai, kocak, dan menarik.
6. Source adalah raja. Jangan menambah atau mengurangi isi cerita.
7. Jangan spoiler dari chapter/scene berikutnya.

GAYA BAHASA:
- Santai sehari-hari, gaul, konyol, lucu, dan kocak.
- Boleh kasar, vulgar, dan santai selama sesuai karakter dan situasi.
- Kalimat pendek, padat, dan tidak kaku (tanpa kalimat puitis/berbunga-bunga klise).
- Karakterisasi tokoh tetap dijaga ketat.
- Bikin pembaca ketawa dan enjoy membaca cerita.

NOTES / KOMENTAR (PENJELASAN ISTILAH & FUN FACT):
- Tambahkan komentar penjelasan istilah atau fun fact singkat dalam tanda kurung siku [Catatan: ...] atau (fun fact: ...) yang RELEVAN dengan istilah asing, sihir, atau budaya yang membingungkan pembaca awam.
- Fun fact singkat, kontekstual, dan jangan menciptakan lore palsu/spoiler.

Output HANYA teks hasil terjemahan yang rapi tanpa kata pengantar atau penutup.`;

function askQuestion(query) {
  const rl = readline.createInterface({ input: process.stdin, output: process.stdout });
  return new Promise(resolve => rl.question(query, ans => {
    rl.close();
    resolve(ans.trim());
  }));
}

function normalizeUrl(rawUrl) {
  let url = rawUrl.trim();
  if (url.endsWith('/')) url = url.slice(0, -1);
  if (!url.endsWith('/chat/completions')) {
    if (url.endsWith('/v1')) {
      url += '/chat/completions';
    } else if (url.includes('googleapis.com') && !url.includes('/openai')) {
      url += '/openai/chat/completions';
    } else {
      url += '/chat/completions';
    }
  }
  return url;
}

function loadConfig() {
  if (fs.existsSync(CONFIG_FILE)) {
    try {
      const data = JSON.parse(fs.readFileSync(CONFIG_FILE, 'utf-8'));
      if (data.apiUrl) data.apiUrl = normalizeUrl(data.apiUrl);
      return { ...DEFAULT_CONFIG, ...data };
    } catch {
      // ignore
    }
  }
  return { ...DEFAULT_CONFIG };
}

function saveConfig(cfg) {
  cfg.apiUrl = normalizeUrl(cfg.apiUrl);
  fs.writeFileSync(CONFIG_FILE, JSON.stringify(cfg, null, 2), 'utf-8');
}

function loadCheckpoint() {
  if (fs.existsSync(CHECKPOINT_FILE)) {
    try {
      return JSON.parse(fs.readFileSync(CHECKPOINT_FILE, 'utf-8'));
    } catch {
      // ignore
    }
  }
  return { lastCompletedId: null, completedIds: [], totalChapters: 0, lastUpdated: new Date().toISOString() };
}

function saveCheckpoint(cp) {
  cp.lastUpdated = new Date().toISOString();
  fs.writeFileSync(CHECKPOINT_FILE, JSON.stringify(cp, null, 2), 'utf-8');
}

async function runInteractiveSetup(cfg) {
  console.log('\n======================================================');
  console.log('⚙️  PENGATURAN SETUP TERMUX TRANSLATOR');
  console.log('======================================================\n');

  const url = await askQuestion(`1. API URL Endpoint [${cfg.apiUrl}]: `);
  if (url) cfg.apiUrl = normalizeUrl(url);

  const key = await askQuestion(`2. API Key [${cfg.apiKey ? cfg.apiKey.substring(0, 8) + '...' : 'Belum diisi'}]: `);
  if (key) cfg.apiKey = key;

  const model = await askQuestion(`3. Model ID [${cfg.model}]: `);
  if (model) cfg.model = model;

  const input = await askQuestion(`4. File Sumber (.txt) [${cfg.inputFile}]: `);
  if (input) cfg.inputFile = input;

  const output = await askQuestion(`5. File Hasil Gabungan (.txt) [${cfg.outputFile}]: `);
  if (output) cfg.outputFile = output;

  const concurrency = await askQuestion(`6. Jumlah Worker Paralel [${cfg.concurrency}]: `);
  if (concurrency) cfg.concurrency = parseInt(concurrency, 10) || 3;

  const chunkSize = await askQuestion(`7. Maks Karakter per Chunk [${cfg.maxChunkChars}]: `);
  if (chunkSize) cfg.maxChunkChars = parseInt(chunkSize, 10) || 10000;

  saveConfig(cfg);
  console.log('\n✅ Pengaturan disimpan ke config.json!');
}

async function parseAllVolumesAndChapters(filePath) {
  if (!fs.existsSync(filePath)) {
    throw new Error(`File sumber tidak ditemukan di: ${path.resolve(filePath)}`);
  }

  const fileStream = fs.createReadStream(filePath, { encoding: 'utf-8' });
  const rl = readline.createInterface({ input: fileStream, crlfDelay: Infinity });

  const chapters = [];
  let currentVol = 1;
  let currentChapter = null;
  let inTocOrDisclaimer = true;

  for await (const rawLine of rl) {
    const line = rawLine.trim();

    const volMatch = rawLine.match(/^ROKUDENASHI MAJUTSU KOUSHI TO AKASHIC RECORDS - VOLUME (\d+)/i);
    if (volMatch) {
      currentVol = parseInt(volMatch[1], 10);
      inTocOrDisclaimer = true;
      continue;
    }

    if (!line) continue;
    if (/^ruidrive\.com$/i.test(line)) continue;
    if (/^Volume \d+$/i.test(line)) continue;
    if (/^QWER - image\d+\./i.test(line)) continue;
    if (/^PDF by:/i.test(line)) continue;

    const isHeading = /^(Prolog|Prologue|Epilog|Epilogue|Bab \d+|Chapter \d+|Kata Penutup|Afterword)/i.test(line);

    if (isHeading) {
      if (rawLine.includes('') || line.length < 3) continue;

      inTocOrDisclaimer = false;

      if (currentChapter && currentChapter.lines.length > 0) {
        chapters.push(currentChapter);
      }

      const chapterIndex = chapters.filter(c => c.volNum === currentVol).length + 1;
      const chId = `vol${String(currentVol).padStart(2, '0')}_ch${String(chapterIndex).padStart(2, '0')}`;

      currentChapter = {
        id: chId,
        volNum: currentVol,
        title: line,
        lines: []
      };
      continue;
    }

    if (inTocOrDisclaimer) continue;

    if (currentChapter) {
      currentChapter.lines.push(line);
    }
  }

  if (currentChapter && currentChapter.lines.length > 0) {
    chapters.push(currentChapter);
  }

  return chapters;
}

function splitIntoParagraphSafeChunks(lines, maxChars) {
  const chunks = [];
  let currentLines = [];
  let currentLength = 0;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    currentLines.push(line);
    currentLength += line.length + 1;

    const isGoodBreakPoint = /[.!?…”"']$/.test(line) || line === '';

    if (currentLength >= maxChars && isGoodBreakPoint) {
      chunks.push(currentLines.join('\n'));
      currentLines = [];
      currentLength = 0;
    }
  }

  if (currentLines.length > 0) {
    chunks.push(currentLines.join('\n'));
  }

  return chunks;
}

// Panggilan LLM Anti-Macet dengan Timeout AbortController & Exponential Backoff
async function callLLM(promptText, previousContext, cfg, retryCount = 5) {
  let userContent = '';
  if (previousContext) {
    userContent = `[KONTEKS KEJADIAN DARI CHUNK SEBELUMNYA (HANYA ACUAN HUBUNGAN CERITA, JANGAN DITERJEMAHKAN LAGI)]:
"...${previousContext.slice(-300)}..."

[LANJUTAN CERITA YANG HARUS DITERJEMAHKAN]:
${promptText}`;
  } else {
    userContent = `[MULAI BAB/ADEGAN]:
${promptText}`;
  }

  const payload = JSON.stringify({
    model: cfg.model,
    messages: [
      { role: 'system', content: SYSTEM_PROMPT },
      { role: 'user', content: userContent }
    ],
    temperature: 0.7,
    stream: false
  });

  for (let attempt = 1; attempt <= retryCount; attempt++) {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), (cfg.requestTimeoutSec || 75) * 1000);

    try {
      const response = await fetch(cfg.apiUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${cfg.apiKey}`
        },
        body: payload,
        signal: controller.signal
      });

      clearTimeout(timeout);

      if (!response.ok) {
        const errorText = await response.text();
        // Deteksi Rate Limit / Quota
        if (response.status === 429) {
          const waitSec = attempt * 8;
          process.stdout.write(`\n⏳ Kena Rate Limit (429). Istirahat ${waitSec} detik... `);
          await new Promise(r => setTimeout(r, waitSec * 1000));
          continue;
        }
        throw new Error(`HTTP ${response.status}: ${errorText.substring(0, 200)}`);
      }

      const json = await response.json();
      const content = json.choices?.[0]?.message?.content;
      if (!content || !content.trim()) {
        throw new Error('Output kosong dari API');
      }

      return content.trim();
    } catch (err) {
      clearTimeout(timeout);
      const isTimeout = err.name === 'AbortError' || err.message.includes('aborted');
      const errMsg = isTimeout ? `Request Timeout (>${cfg.requestTimeoutSec || 75}s)` : err.message;

      if (attempt === retryCount) {
        throw new Error(`Gagal setelah ${retryCount}x percobaan: ${errMsg}`);
      }

      const retryWait = attempt * 3;
      process.stdout.write(`\n⚠️  [Retry ${attempt}/${retryCount}] ${errMsg}. Tunggu ${retryWait}s... `);
      await new Promise(r => setTimeout(r, retryWait * 1000));
    }
  }

  throw new Error('Gagal menghubungi API');
}

async function mapConcurrent(items, limit, fn) {
  const results = new Array(items.length);
  let nextIdx = 0;

  async function worker() {
    while (nextIdx < items.length) {
      const current = nextIdx++;
      results[current] = await fn(items[current], current);
    }
  }

  const workers = Array.from({ length: Math.min(limit, items.length) }, () => worker());
  await Promise.all(workers);
  return results;
}

async function startTranslation(cfg) {
  console.log('\n======================================================');
  console.log('🚀 MEMULAI PROSES TRANSLASI BATCH (ANTI-HANG ENGINE)');
  console.log('======================================================');
  console.log(`📁 File Input  : ${cfg.inputFile}`);
  console.log(`📄 File Output : ${cfg.outputFile}`);
  console.log(`🤖 Model       : ${cfg.model}`);
  console.log(`🌐 Endpoint    : ${cfg.apiUrl}`);
  console.log(`⚡ Concurrency : ${cfg.concurrency} worker paralel`);
  console.log('======================================================\n');

  console.log('🔍 Membaca dan memetakan struktur bab...');
  const chapters = await parseAllVolumesAndChapters(cfg.inputFile);
  console.log(`✅ Berhasil memetakan ${chapters.length} Bab dari seluruh Volume.\n`);

  const checkpoint = loadCheckpoint();
  checkpoint.totalChapters = chapters.length;

  let lastVol = 0;

  for (let i = 0; i < chapters.length; i++) {
    const ch = chapters[i];

    if (checkpoint.completedIds.includes(ch.id)) {
      console.log(`⏭️  [${i + 1}/${chapters.length}] Bab ${ch.id} (${ch.title}) sudah selesai. Lewati.`);
      lastVol = ch.volNum;
      continue;
    }

    console.log(`\n------------------------------------------------------`);
    console.log(`📖 [${i + 1}/${chapters.length}] Memproses: Volume ${ch.volNum} - ${ch.title} (${ch.lines.length} baris)`);
    console.log(`------------------------------------------------------`);

    let volumeHeader = '';
    if (ch.volNum !== lastVol) {
      volumeHeader = `\n\n${'='.repeat(80)}\nROKUDENASHI MAJUTSU KOUSHI TO AKASHIC RECORDS - VOLUME ${String(ch.volNum).padStart(2, '0')}\n${'='.repeat(80)}\n\n`;
      lastVol = ch.volNum;
    }

    const chunks = splitIntoParagraphSafeChunks(ch.lines, cfg.maxChunkChars);
    console.log(`📦 Bab ini dibagi menjadi ${chunks.length} bagian adegan.`);

    const startTime = Date.now();
    const translatedChunks = await mapConcurrent(chunks, cfg.concurrency, async (chunkText, idx) => {
      const prevContext = idx > 0 ? chunks[idx - 1] : null;
      const cStart = Date.now();
      const res = await callLLM(chunkText, prevContext, cfg);
      const cDuration = ((Date.now() - cStart) / 1000).toFixed(1);
      console.log(`   ⚡ Bagian [${idx + 1}/${chunks.length}] selesai dalam ${cDuration}s`);
      return res;
    });

    const totalDuration = ((Date.now() - startTime) / 1000).toFixed(1);
