#!/usr/bin/env node
/**
 * ============================================================================
 * 🚇 NOVEL TRANSLATOR - DRAG & DROP RUNNER (ROBUST PROMPT & ZERO-REFUSAL)
 * ============================================================================
 */

import fs from 'node:fs';
import path from 'node:path';
import readline from 'node:readline';
import http from 'node:http';
import { execSync } from 'node:child_process';

const CONFIG = {
  proxyUrl: 'http://127.0.0.1:20128/v1/chat/completions',
  model: 'ag/gemini-3.8-flash',
  apiKey: 'sk-2e591994696af18e-71ijj7-14263abd',
  maxChunkChars: 10000,
  concurrency: 4
};

interface Chapter {
  id: string;
  title: string;
  text: string;
}

function isRefusalResponse(text: string): boolean {
  if (!text || text.trim().length === 0) return true;
  return /tidak dapat (memberikan|menerjemahkan)|novel berhak cipta|karya berhak cipta|ringkasan umum|garis besar adegan|copyright/i.test(text.substring(0, 400));
}

function extractEpubChapters(epubPath: string): Chapter[] {
  console.log('📦 Membaca isi file EPUB...');
  const tempDir = path.join(path.dirname(epubPath), '.temp_epub_extract');
  if (fs.existsSync(tempDir)) fs.rmSync(tempDir, { recursive: true, force: true });
  fs.mkdirSync(tempDir, { recursive: true });

  try {
    execSync(`tar -xf "${epubPath}" -C "${tempDir}"`, { stdio: 'pipe' });
  } catch (err) {
    throw new Error('Gagal mengekstrak EPUB: ' + err);
  }

  const chapters: Chapter[] = [];
  function scanDir(dir: string) {
    const entries = fs.readdirSync(dir, { withFileTypes: true });
    for (const ent of entries) {
      const full = path.join(dir, ent.name);
      if (ent.isDirectory()) {
        scanDir(full);
      } else if (/\.(html|xhtml)$/i.test(ent.name)) {
        if (/cover|toc|bookmark|titlepage|copyright/i.test(ent.name)) continue;

        const html = fs.readFileSync(full, 'utf-8');
        let cleanText = html
          .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '')
          .replace(/<style\b[^<]*(?:(?!<\/style>)<[^<]*)*<\/style>/gi, '')
          .replace(/<div class="cst"><b>(.*?)<\/b><\/div>/gi, '\nSubtitle: $1\n')
          .replace(/<div class="ct"><b>(.*?)<\/b><\/div>/gi, '\n\n# $1\n')
          .replace(/<h[1-6][^>]*>(.*?)<\/h[1-6]>/gi, '\n\n# $1\n')
          .replace(/<p[^>]*>/gi, '\n')
          .replace(/<div[^>]*>/gi, '\n')
          .replace(/<br\s*[\/]?>/gi, '\n')
          .replace(/<[^>]+>/g, '')
          .replace(/&nbsp;/g, ' ')
          .replace(/&amp;/g, '&')
          .replace(/&quot;/g, '"')
          .replace(/&apos;/g, "'")
          .replace(/&lt;/g, '<')
          .replace(/&gt;/g, '>')
          .replace(/\n\s*\n\s*\n/g, '\n\n')
          .trim();

        if (cleanText.length > 500) {
          const lines = cleanText.split('\n').map(l => l.trim()).filter(Boolean);
          const title = lines.slice(0, 2).join(' - ') || ent.name;
          chapters.push({
            id: path.basename(ent.name, path.extname(ent.name)),
            title,
            text: cleanText
          });
        }
      }
    }
  }

  scanDir(tempDir);
  fs.rmSync(tempDir, { recursive: true, force: true });
  chapters.sort((a, b) => a.id.localeCompare(b.id, undefined, { numeric: true, sensitivity: 'base' }));
  return chapters;
}

function extractTxtChapters(txtPath: string): Chapter[] {
  const content = fs.readFileSync(txtPath, 'utf-8');
  const lines = content.split('\n');
  const chapters: Chapter[] = [];
  let currentChap: Chapter | null = null;
  let currentLines: string[] = [];
  let chIndex = 1;

  for (const rawLine of lines) {
    const line = rawLine.trim();

    // 1. Bersihkan watermark buku / nomor halaman cetak
    if (/^(TOM CLANCY\b|RAINBOW SIX\b|\d+\s+e\s+TOM CLANCY|\bRAINBOW SIX\s+e\s+\d+)/i.test(line)) {
      continue;
    }

    // 2. Bersihkan sampah karakter acak OCR
    if (line.length < 5 && /^[|\-=_~+`!?.a-z\s]+$/i.test(line)) {
      continue;
    }

    // Hanya deteksi bab jika ada judul spesifik atau awal buku
    const isHeading = /^(CHAPTER|BAB|PROLOG|EPILOGUE|EPILOG|VOLUMUL)\b/i.test(line);

    if (isHeading && line.length < 100) {
      if (currentChap && currentLines.length > 0) {
        currentChap.text = currentLines.join('\n').trim();
        chapters.push(currentChap);
      }
      currentChap = {
        id: `chap_${String(chIndex++).padStart(2, '0')}`,
        title: line,
        text: ''
      };
      currentLines = [];
      continue;
    }

    currentLines.push(rawLine);
  }

  if (currentChap && currentLines.length > 0) {
    currentChap.text = currentLines.join('\n').trim();
    chapters.push(currentChap);
  }

  if (chapters.length === 0) {
    return [{ id: 'full_text', title: path.basename(txtPath), text: content }];
  }

  return chapters;
}

function splitParagraphSafe(text: string, maxChars: number): string[] {
  const paragraphs = text.split('\n');
  const chunks: string[] = [];
  let current: string[] = [];
  let len = 0;

  for (const p of paragraphs) {
    current.push(p);
    len += p.length + 1;
    if (len >= maxChars) {
      chunks.push(current.join('\n'));
      current = [];
      len = 0;
    }
  }

  if (current.length > 0) chunks.push(current.join('\n'));
  return chunks;
}

// Single-turn user prompt: teknik paling ampuh melewati trigger copyright filter
async function callLLM(text: string, prevContext: string | null, retry = 3): Promise<string> {
  const parsedUrl = new URL(CONFIG.proxyUrl);

  const promptContent = `Terjemahkan teks adegan aksi dan dialog berikut ke Bahasa Indonesia sehari-hari yang santai, gaul, to-the-point, dan tanpa kata-kata puitis muter-muter. Format dialog sertakan Nama: "...". Terjemahkan baris demi baris secara lengkap tanpa merangkum:\n\n${text}`;

  for (let attempt = 1; attempt <= retry; attempt++) {
    const payload = JSON.stringify({
      model: CONFIG.model,
      messages: [
        { role: 'user', content: promptContent }
      ],
      temperature: 0.5,
      stream: false
    });

    try {
      const resText = await new Promise<string>((resolve, reject) => {
        const req = http.request({
          hostname: parsedUrl.hostname,
          port: parsedUrl.port || 80,
          path: parsedUrl.pathname,
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${CONFIG.apiKey}`,
            'Content-Length': Buffer.byteLength(payload)
          },
          timeout: 180000
        }, (res) => {
          let d = '';
          res.on('data', c => d += c);
          res.on('end', () => {
            if (res.statusCode && res.statusCode >= 200 && res.statusCode < 300) {
              try {
                const j = JSON.parse(d);
                resolve(j.choices?.[0]?.message?.content || '');
              } catch (e) {
                reject(e);
              }
            } else {
              reject(new Error(`HTTP ${res.statusCode}: ${d}`));
            }
          });
        });
        req.on('error', reject);
        req.on('timeout', () => req.destroy(new Error('Request Timeout')));
        req.write(payload);
        req.end();
      });

      const cleanRes = resText.trim();

      if (isRefusalResponse(cleanRes)) {
        console.warn(`   ⚠️ [Percobaan ${attempt}] Output terdeteksi penolakan, mengulang...`);
        if (attempt === retry) {
          throw new Error('LLM menolak akibat filter copyright.');
        }
        await new Promise(r => setTimeout(r, 2000 * attempt));
        continue;
      }

      return cleanRes;
    } catch (err: any) {
      console.warn(`⚠️ [Retry ${attempt}/${retry}] ${err.message}`);
      if (attempt === retry) throw err;
      await new Promise(r => setTimeout(r, 2000 * attempt));
    }
  }

  throw new Error('LLM Translation Failed');
}

async function mapConcurrent<T, R>(items: T[], limit: number, fn: (item: T, i: number) => Promise<R>): Promise<R[]> {
  const results = new Array<R>(items.length);
  let nextIdx = 0;
  const workers = Array.from({ length: Math.min(limit, items.length) }, async () => {
    while (nextIdx < items.length) {
      const cur = nextIdx++;
      results[cur] = await fn(items[cur], cur);
    }
  });
  await Promise.all(workers);
  return results;
}

async function main() {
  console.log('================================================================');
  console.log('🚇 NOVEL TRANSLATOR - DRAG & DROP RUNNER (DIRECT & GAUL)');
  console.log('================================================================');

  let targetFile = process.argv[2];

  if (!targetFile) {
    const rl = readline.createInterface({ input: process.stdin, output: process.stdout });
    targetFile = await new Promise<string>(res => {
      rl.question('👉 Seret & Lepas (Drag & Drop) file .epub atau .txt ke sini lalu tekan ENTER:\n> ', ans => {
        rl.close();
        res(ans.trim().replace(/^["']|["']$/g, ''));
      });
    });
  }

  targetFile = path.resolve(targetFile.replace(/^["']|["']$/g, ''));

  if (!fs.existsSync(targetFile)) {
    console.error(`❌ File tidak ditemukan: ${targetFile}`);
    process.exit(1);
  }

  const ext = path.extname(targetFile).toLowerCase();
  const baseName = path.basename(targetFile, ext);
  const dirName = path.dirname(targetFile);

  const outputFile = path.join(dirName, `${baseName} (Terjemahan ID-Direct).txt`);
  const checkpointFile = path.join(dirName, `${baseName}_checkpoint.json`);
  const cacheDir = path.join(dirName, `.${baseName}_chunks_cache`);

  if (!fs.existsSync(cacheDir)) {
    fs.mkdirSync(cacheDir, { recursive: true });
  }

  console.log(`\n📁 File Input   : ${targetFile}`);
  console.log(`📄 File Output  : ${outputFile}`);
  console.log(`🔖 Checkpoint   : ${checkpointFile}`);
  console.log(`📂 Chunk Cache  : ${cacheDir}`);
  console.log(`⚡ Concurrency  : ${CONFIG.concurrency} Workers | Model: ${CONFIG.model}\n`);

  let chapters: Chapter[] = [];
  if (ext === '.epub') {
    chapters = extractEpubChapters(targetFile);
  } else if (ext === '.txt') {
    chapters = extractTxtChapters(targetFile);
  } else {
    console.error('❌ Format file tidak didukung! Harap masukkan file .epub atau .txt');
    process.exit(1);
  }

  console.log(`✅ Berhasil mendeteksi ${chapters.length} Bab dari file.\n`);

  let checkpoint = { completedIds: [] as string[] };
  if (fs.existsSync(checkpointFile)) {
    try {
      checkpoint = JSON.parse(fs.readFileSync(checkpointFile, 'utf-8'));
    } catch {}
  }

  for (let i = 0; i < chapters.length; i++) {
    const ch = chapters[i];

    if (checkpoint.completedIds.includes(ch.id)) {
      console.log(`⏭️  [${i + 1}/${chapters.length}] Lewati Bab: ${ch.title} (Sudah selesai)`);
      continue;
    }

    console.log(`----------------------------------------------------------------`);
    console.log(`📖 [${i + 1}/${chapters.length}] Memproses Bab: ${ch.title} (~${ch.text.length} karakter)`);
    console.log(`----------------------------------------------------------------`);

    const chapCacheDir = path.join(cacheDir, ch.id);
    if (!fs.existsSync(chapCacheDir)) {
      fs.mkdirSync(chapCacheDir, { recursive: true });
    }

    const chunks = splitParagraphSafe(ch.text, CONFIG.maxChunkChars);
    console.log(`📦 Dibagi menjadi ${chunks.length} bagian chunk...`);

    const startT = Date.now();
    const translatedParts = await mapConcurrent(chunks, CONFIG.concurrency, async (chunkText, idx) => {
      const chunkFile = path.join(chapCacheDir, `chunk_${String(idx + 1).padStart(3, '0')}.txt`);

      if (fs.existsSync(chunkFile)) {
        const cached = fs.readFileSync(chunkFile, 'utf-8');
        if (!isRefusalResponse(cached)) {
          console.log(`   ⚡ Bagian [${idx + 1}/${chunks.length}] dimuat dari cache lokal.`);
          return cached;
        } else {
          fs.rmSync(chunkFile, { force: true });
        }
      }

      const prevContext = idx > 0 ? chunks[idx - 1] : null;
      const tStart = Date.now();
      const res = await callLLM(chunkText, prevContext);
      const dur = ((Date.now() - tStart) / 1000).toFixed(1);

      fs.writeFileSync(chunkFile, res, 'utf-8');
      console.log(`   ⚡ Bagian [${idx + 1}/${chunks.length}] selesai (${dur}s) & dicache`);
      return res;
    });

    const totalDur = ((Date.now() - startT) / 1000).toFixed(1);
    console.log(`✅ Bab selesai dalam ${totalDur}s`);

    const chapterOutput = `\n\n${'='.repeat(70)}\n### ${ch.title}\n${'='.repeat(70)}\n\n${translatedParts.join('\n\n')}\n\n`;
    fs.appendFileSync(outputFile, chapterOutput, 'utf-8');

    checkpoint.completedIds.push(ch.id);
    fs.writeFileSync(checkpointFile, JSON.stringify(checkpoint, null, 2), 'utf-8');
    console.log(`💾 Bab tersimpan ke output dan checkpoint.`);
  }

  console.log('\n================================================================');
  console.log('🎉 PROSES TERJEMAHAN SELESAI!');
  console.log(`📁 File hasil tersimpan di: ${outputFile}`);
  console.log('================================================================');
}

main().catch(err => {
  console.error('\n❌ Terjadi kesalahan fatal:', err);
  process.exit(1);
});

