async function translateTitle(rawTitle: string): Promise<string> {
  const cleanTitle = rawTitle.replace(/^#+\s*/, '').trim();
  if (/^PROLOG/i.test(cleanTitle)) return 'PROLOG';
  if (/^EPILOG/i.test(cleanTitle)) return 'EPILOG';

  try {
    const parsedUrl = new URL(CONFIG.proxyUrl);
    const payload = JSON.stringify({
      model: CONFIG.model,
      messages: [
        { role: 'user', content: `Terjemahkan judul bab berikut ke Bahasa Indonesia to-the-point dan singkat tanpa tanda kutip:\n\n${cleanTitle}` }
      ],
