#!/usr/bin/env node
/**
 * ============================================================================
 * 🚇 NOVEL TRANSLATOR - DRAG & DROP RUNNER (ROBUST PROMPT & ZERO-REFUSAL)
 * Multi-Chapter Fast Pipeline with Resume & Auto Sub-Chunk Fallback
 * ============================================================================
 */

import fs from 'node:fs';
import path from 'node:path';
import readline from 'node:readline';
import http from 'node:http';
import { execSync } from 'node:child_process';

const CONFIG = {
  proxyUrl: 'http://127.0.0.1:20128/v1/chat/completions',
  model: 'ag/gemini-3.8-flash',
  apiKey: 'sk-2e591994696af18e-71ijj7-14263abd',
  maxChunkChars: 6500, // Diperkecil ke 6500 chars agar jauh lebih aman dari filter threshold
  concurrency: 3
};

interface Chapter {
  id: string;
  title: string;
  text: string;
}

function parseSSEorJSON(raw: string): string {
  let full = '';
  const lines = raw.split('\n');
  for (const l of lines) {
    if (l.startsWith('data: ') && !l.includes('[DONE]')) {
      try {
        const j = JSON.parse(l.substring(6));
        const delta = j.choices?.[0]?.delta?.content || j.choices?.[0]?.message?.content || '';
        full += delta;
      } catch {}
    }
  }

  if (!full && raw.trim().startsWith('{')) {
    try {
      const j = JSON.parse(raw.trim());
      if (j.response?.promptFeedback?.blockReason) {
        console.warn(`   ⚠️ Gemini Block Filter: ${j.response.promptFeedback.blockReasonMessage || j.response.promptFeedback.blockReason}`);
        return '';
      }
      return j.choices?.[0]?.message?.content || '';
    } catch {}
  }

  return full.trim();
}

function isRefusalResponse(text: string): boolean {
  if (!text || text.trim().length === 0) return true;
  return /tidak dapat (memberikan|menerjemahkan)|novel berhak cipta|karya berhak cipta|ringkasan umum|garis besar adegan|hak cipta melarang/i.test(text.substring(0, 350));
}

function cleanWatermarks(text: string): string {
  return text
    .replace(/\b\d+\s*e\s*TOM\s*CLANCY\b/gi, '')
    .replace(/\bTOM\s*CLANCY\s*e\s*\d+\b/gi, '')
    .replace(/\bTOM\s*CLANCY\b/gi, '')
    .replace(/\bTOMCLANCY\b/gi, '')
    .replace(/\bRAINBOW\s*SIX(\s*e\s*\d+)?\b/gi, '')
    .replace(/\n\s*\n\s*\n/g, '\n\n')
    .trim();
}

function extractEpubChapters(epubPath: string): Chapter[] {
  console.log('📦 Membaca isi file EPUB...');
  const tempDir = path.join(path.dirname(epubPath), '.temp_epub_extract');
  if (fs.existsSync(tempDir)) fs.rmSync(tempDir, { recursive: true, force: true });
  fs.mkdirSync(tempDir, { recursive: true });

  try {
    execSync(`tar -xf "${epubPath}" -C "${tempDir}"`, { stdio: 'pipe' });
  } catch (err) {
    throw new Error('Gagal mengekstrak EPUB: ' + err);
  }

  const chapters: Chapter[] = [];
  function scanDir(dir: string) {
    const entries = fs.readdirSync(dir, { withFileTypes: true });
    for (const ent of entries) {
      const full = path.join(dir, ent.name);
      if (ent.isDirectory()) {
        scanDir(full);
      } else if (/\.(html|xhtml)$/i.test(ent.name)) {
        if (/cover|toc|bookmark|titlepage|copyright/i.test(ent.name)) continue;

        const html = fs.readFileSync(full, 'utf-8');
        let cleanText = html
          .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '')
          .replace(/<style\b[^<]*(?:(?!<\/style>)<[^<]*)*<\/style>/gi, '')
          .replace(/<div class="cst"><b>(.*?)<\/b><\/div>/gi, '\nSubtitle: $1\n')
          .replace(/<div class="ct"><b>(.*?)<\/b><\/div>/gi, '\n\n# $1\n')
          .replace(/<h[1-6][^>]*>(.*?)<\/h[1-6]>/gi, '\n\n# $1\n')
          .replace(/<p[^>]*>/gi, '\n')
          .replace(/<div[^>]*>/gi, '\n')
          .replace(/<br\s*[\/]?>/gi, '\n')
          .replace(/<[^>]+>/g, '')
          .replace(/&nbsp;/g, ' ')
          .replace(/&amp;/g, '&')
          .replace(/&quot;/g, '"')
          .replace(/&apos;/g, "'")
          .replace(/&lt;/g, '<')
          .replace(/&gt;/g, '>')
          .replace(/\n\s*\n\s*\n/g, '\n\n')
          .trim();

        if (cleanText.length > 500) {
          const lines = cleanText.split('\n').map(l => l.trim()).filter(Boolean);
          const title = lines.slice(0, 2).join(' - ') || ent.name;
          chapters.push({
            id: path.basename(ent.name, path.extname(ent.name)),
            title,
            text: cleanWatermarks(cleanText)
          });
        }
      }
    }
  }

  scanDir(tempDir);
  fs.rmSync(tempDir, { recursive: true, force: true });
  chapters.sort((a, b) => a.id.localeCompare(b.id, undefined, { numeric: true, sensitivity: 'base' }));
  return chapters;
}

function extractTxtChapters(txtPath: string): Chapter[] {
  const content = fs.readFileSync(txtPath, 'utf-8');
