function splitParagraphSafe(text: string, maxChars: number): string[] {
  const paragraphs = text.split('\n');
  const chunks: string[] = [];
  let current: string[] = [];
  let len = 0;

  for (const p of paragraphs) {
    current.push(p);
    len += p.length + 1;
    if (len >= maxChars) {
      chunks.push(current.join('\n'));
      current = [];
      len = 0;
    }
  }

  if (current.length > 0) chunks.push(current.join('\n'));
  return chunks;
}

async function callLLMSingle(text: string): Promise<string> {
  const parsedUrl = new URL(CONFIG.proxyUrl);
  const sanitizedText = cleanWatermarks(text);
  const promptContent = `Berikut adalah draf adegan fiksi novel aksi laga petualangan berbahasa Rumania. Tolong terjemahkan naskah cerita fiksi ini ke Bahasa Indonesia santai (lu-gue) to-the-point tanpa bertele-tele. Format dialog sertakan Nama: "...". Terjemahkan baris demi baris secara lengkap:\n\n${sanitizedText}`;

  const payload = JSON.stringify({
    model: CONFIG.model,
    messages: [
      { role: 'user', content: promptContent }
    ],
    temperature: 0.6,
    stream: false
  });

  const rawResponse = await new Promise<string>((resolve, reject) => {
    const req = http.request({
      hostname: parsedUrl.hostname,
      port: parsedUrl.port || 80,
      path: parsedUrl.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${CONFIG.apiKey}`,
        'Content-Length': Buffer.byteLength(payload)
      },
      timeout: 180000
    }, (res) => {
      let d = '';
      res.on('data', c => d += c);
      res.on('end', () => {
        if (res.statusCode && res.statusCode >= 200 && res.statusCode < 300) {
          resolve(d);
        } else {
          reject(new Error(`HTTP ${res.statusCode}: ${d}`));
        }
      });
    });
    req.on('error', reject);
    req.on('timeout', () => req.destroy(new Error('Request Timeout')));
    req.write(payload);
    req.end();
  });

  return parseSSEorJSON(rawResponse);
}

async function callLLM(text: string, prevContext: string | null, retry = 3): Promise<string> {
  for (let attempt = 1; attempt <= retry; attempt++) {
    try {
      const res = await callLLMSingle(text);

      if (!isRefusalResponse(res) && res.length >= 50) {
        return res;
      }

      console.warn(`   ⚠️ [Percobaan ${attempt}] Output ditolak filter (${res.length} chars). Menerapkan strategi pemecahan sub-chunk...`);
    } catch (err: any) {
      console.warn(`   ⚠️ [Percobaan ${attempt}] Error: ${err.message}`);
    }

    // Strategi Auto Sub-Chunking: Jika teks kena filter dan panjangnya > 2000 chars, belah menjadi 2 bagian!
    if (text.length > 2000) {
      const lines = text.split('\n');
      const mid = Math.floor(lines.length / 2);
      const part1 = lines.slice(0, mid).join('\n').trim();
      const part2 = lines.slice(mid).join('\n').trim();

      if (part1 && part2) {
        console.log(`   ✂️ Membagi chunk bermasalah menjadi 2 sub-bagian (${part1.length} chars & ${part2.length} chars)...`);
        try {
          const res1 = await callLLM(part1, null, 2);
          const res2 = await callLLM(part2, null, 2);
          return `${res1}\n\n${res2}`;
        } catch (subErr) {
          console.warn(`   ⚠️ Sub-chunk split juga mengalami kendala, mencoba ulang...`);
        }
      }
    }

    await new Promise(r => setTimeout(r, 2000 * attempt));
  }

  throw new Error('LLM Translation Failed after retries and sub-chunk splits.');
}

async function mapConcurrent<T, R>(items: T[], limit: number, fn: (item: T, i: number) => Promise<R>): Promise<R[]> {
  const results = new Array<R>(items.length);
  let nextIdx = 0;
  const workers = Array.from({ length: Math.min(limit, items.length) }, async () => {
    while (nextIdx < items.length) {
      const cur = nextIdx++;
      results[cur] = await fn(items[cur], cur);
    }
  });
  await Promise.all(workers);
  return results;
}

