const fs = require('fs');

const target = 'D:/JV/[Ruidrive] Kono Subarashii Sekai ni Bakuen wo!/[Ruidrive] Kono Subarashii Sekai ni Bakuen wo!/[Ruidrive] Kono Subarashii Sekai ni Bakuen wo! - Volume 17.1/Kono Subarashii Sekai ni Shukufuku wo! - Volume 01-17 + Bakuen 17.1.txt';
const content = fs.readFileSync(target, 'utf8');
const lines = content.split('\n');

const chapters = [];
let currentVol = 'Volume 01';
let curChap = null;
let curLines = [];

for (let i = 0; i < lines.length; i++) {
  const rawLine = lines[i];
  const l = rawLine.trim();

  // Deteksi Volume baru
  const vm = l.match(/^KONO SUBARASHII SEKAI NI SHUKUFUKU WO! - (VOLUME\s+[0-9]+(?:\.[0-9]+)?)/i);
  if (vm) {
    if (curChap) {
      curChap.text = curLines.join('\n').trim();
      if (curChap.text.length > 500) chapters.push(curChap);
    }
    currentVol = vm[1];
    curChap = null;
    curLines = [];
    continue;
  }

  // Filter watermark PDF
  if (/^(PDF\s+KONOSUBA\s+Vol|Konosuba\s+[–-]\s+Volume|Ruidrive\.com|Author\s*:|Illustrasi\s*:|Illustrator\s*:|PDF\s+By\s*:|PDF\s+dan\s+dowload|Kono\s+Subarashii\s+Sekai|List\s+chapter|Index|Attention|Warning!|\d+$)/i.test(l)) {
    continue;
  }

  // Deteksi Bab (Chapter, Prologue, Epilogue, Short Story, Interlude)
  const isChap = /^(Chapter\s+[0-9]+|Prologue|Epilogue|Interlude|Short\s+Story|Extra)/i.test(l);
  if (isChap && curLines.length > 50) {
    if (curChap) {
      curChap.text = curLines.join('\n').trim();
      if (curChap.text.length > 500) chapters.push(curChap);
    }
    curChap = {
      vol: currentVol,
      title: `${currentVol} - ${l}`,
      text: ''
    };
    curLines = [];
    continue;
  }

  curLines.push(rawLine);
}

if (curChap) {
  curChap.text = curLines.join('\n').trim();
  if (curChap.text.length > 500) chapters.push(curChap);
}

console.log('Total Bab terdeteksi:', chapters.length);
console.log('Sample 10 Bab pertama:');
for (let i = 0; i < Math.min(10, chapters.length); i++) {
  console.log(`[${i+1}] ${chapters[i].title} (~${chapters[i].text.length} chars)`);
}
console.log('Sample 10 Bab terakhir:');
for (let i = Math.max(0, chapters.length - 10); i < chapters.length; i++) {
  console.log(`[${i+1}] ${chapters[i].title} (~${chapters[i].text.length} chars)`);
}

