500: async function mapConcurrent<T, R>(items: T[], limit: number, fn: (item: T, i: number) => Promise<R>): Promise<R[]> {
501:   const results = new Array<R>(items.length);
502:   let nextIdx = 0;
503:   const workers = Array.from({ length: Math.min(limit, items.length) }, async () => {
504:     while (nextIdx < items.length) {
505:       const cur = nextIdx++;
506:       results[cur] = await fn(items[cur], cur);
507:     }
508:   });
509:   await Promise.all(workers);
510:   return results;
511: }
