function cleanWatermarks(text: string): string {
  return text
    .replace(/PDF\s+KONOSUBA\s+Vol(?:\w+)?\s*\d*/gi, '')
    .replace(/Konosuba\s+[–-]\s+Volume\s*\d+(?:\.\d+)?/gi, '')
