async function callLLM(text: string, prevContext: string | null, styleMode: 'konosuba' | 'warhammer' | 'default', retry = 3): Promise<string> {
  for (let attempt = 1; attempt <= retry; attempt++) {
    try {
      const needSanitize = attempt > 1;
