      if (!isRefusalResponse(res) && res.length >= 50) {
        return res;
      }

      console.warn(`   ⚠️ [Percobaan ${attempt}] Output ditolak filter (${res.length} chars). Menerapkan strategi pemecahan sub-chunk & sanitasi...`);
    } catch (err: any) {
      console.warn(`   ⚠️ [Percobaan ${attempt}] Error: ${err.message}`);
    }

    if (text.length > 2000) {
      const lines = text.split('\n');
      const mid = Math.floor(lines.length / 2);
      const part1 = lines.slice(0, mid).join('\n').trim();
      const part2 = lines.slice(mid).join('\n').trim();

      if (part1 && part2) {
        console.log(`   ✂️ Membagi chunk bermasalah menjadi 2 sub-bagian (${part1.length} chars & ${part2.length} chars)...`);
        try {
          const res1 = await callLLMSingle(part1, styleMode, true);
          const res2 = await callLLMSingle(part2, styleMode, true);
          if (res1.length >= 50 && res2.length >= 50 && !isRefusalResponse(res1) && !isRefusalResponse(res2)) {
            return `${res1}\n\n${res2}`;
          }
        } catch (subErr) {
          console.warn(`   ⚠️ Sub-chunk split juga mengalami kendala, mencoba ulang...`);
        }
      }
    }

    await new Promise(r => setTimeout(r, 2000 * attempt));
  }

  throw new Error('LLM Translation Failed after retries and sub-chunk splits.');
}

async function mapConcurrent<T, R>(items: T[], limit: number, fn: (item: T, i: number) => Promise<R>): Promise<R[]> {
  const results = new Array<R>(items.length);
  let nextIdx = 0;
  const workers = Array.from({ length: Math.min(limit, items.length) }, async () => {
    while (nextIdx < items.length) {
      const cur = nextIdx++;
      results[cur] = await fn(items[cur], cur);
    }
  });
  await Promise.all(workers);
  return results;
}

