        z.writestr("OEBPS/nav.xhtml", nav_xhtml, compress_type=zipfile.ZIP_DEFLATED)

        cover_id = f"img_{color_images[0].replace('.', '_')}" if color_images else "item_1"
        content_opf = f"""<?xml version="1.0" encoding="UTF-8"?>
