459: function splitParagraphSafe(text: string, maxChars: number): string[] {
460:   const paragraphs = text.split('\n');
461:   const chunks: string[] = [];
462:   let current: string[] = [];
463:   let len = 0;
464: 
465:   for (const p of paragraphs) {
466:     current.push(p);
467:     len += p.length + 1;
468:     if (len >= maxChars) {
469:       chunks.push(current.join('\n'));
470:       current = [];
471:       len = 0;
472:     }
473:   }
474: 
475:   if (current.length > 0) chunks.push(current.join('\n'));
476:   return chunks;
477: }
