609: async function mapConcurrent<T, R>(items: T[], limit: number, fn: (item: T, i: number) => Promise<R>): Promise<R[]> {
610:   const results = new Array<R>(items.length);
611:   let nextIdx = 0;
612:   const workers = Array.from({ length: Math.min(limit, items.length) }, async () => {
613:     while (nextIdx < items.length) {
614:       const cur = nextIdx++;
615:       results[cur] = await fn(items[cur], cur);
616:     }
617:   });
618:   await Promise.all(workers);
619:   return results;
620: }
