async function callLLMSingle(text: string, styleMode: 'konosuba' | 'warhammer' | 'hobbit' | 'default', sanitize = false): Promise<string> {
  const parsedUrl = new URL(CONFIG.proxyUrl);
  let processedText = cleanWatermarks(text);
  if (sanitize || styleMode === 'konosuba') {
    processedText = sanitizeSensitiveWords(processedText);
  }

  const promptContent = buildPrompt(processedText, styleMode);

  const payload = JSON.stringify({
    model: CONFIG.model,
    messages: [
      { role: 'user', content: promptContent }
    ],
    temperature: styleMode === 'konosuba' ? 0.7 : 0.6,
    stream: false
  });

  const rawResponse = await new Promise<string>((resolve, reject) => {
    const req = http.request({
      hostname: parsedUrl.hostname,
      port: parsedUrl.port || 80,
      path: parsedUrl.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${CONFIG.apiKey}`,
        'Content-Length': Buffer.byteLength(payload)
      },
      timeout: 180000
    }, (res) => {
      let d = '';
      res.on('data', c => d += c);
      res.on('end', () => {
        if (res.statusCode && res.statusCode >= 200 && res.statusCode < 300) {
          resolve(d);
        } else {
          reject(new Error(`HTTP ${res.statusCode}: ${d}`));
        }
      });
    });
    req.on('error', reject);
    req.on('timeout', () => req.destroy(new Error('Request Timeout')));
    req.write(payload);
    req.end();
  });

  return parseSSEorJSON(rawResponse);
}

