async function callLLM(text: string, prevContext: string | null, styleMode: 'konosuba' | 'warhammer' | 'hobbit' | 'default', retry = 5): Promise<string> {
  for (let attempt = 1; attempt <= retry; attempt++) {
    try {
      const needSanitize = attempt > 1;
      const res = await callLLMSingle(text, styleMode, needSanitize);

      if (!isRefusalResponse(res) && res.length >= 50) {
        return res;
      }

      console.warn(`   ⚠️ [Percobaan ${attempt}] Output ditolak filter (${res.length} chars). Menerapkan strategi pemecahan sub-chunk & sanitasi...`);
    } catch (err: any) {
      console.warn(`   ⚠️ [Percobaan ${attempt}] Error: ${err.message}`);
      if (/ECONNREFUSED|ECONNRESET|ETIMEDOUT/i.test(err.message)) {
        console.warn(`   ⏳ Koneksi proxy sedang terputus, menunggu 5 detik sebelum coba lagi...`);
        await new Promise(r => setTimeout(r, 5000));
        continue;
      }
    }

    if (text.length > 2000) {
      const lines = text.split('\n');
      const mid = Math.floor(lines.length / 2);
      const part1 = lines.slice(0, mid).join('\n').trim();
      const part2 = lines.slice(mid).join('\n').trim();

      if (part1 && part2) {
        console.log(`   ✂️ Membagi chunk bermasalah menjadi 2 sub-bagian (${part1.length} chars & ${part2.length} chars)...`);
        try {
