754: function splitParagraphSafe(text: string, maxChars: number): string[] {
755:   const paragraphs = text.split('\n');
756:   const chunks: string[] = [];
757:   let current: string[] = [];
758:   let len = 0;
759: 
760:   for (const p of paragraphs) {
761:     current.push(p);
762:     len += p.length + 1;
763:     if (len >= maxChars) {
764:       chunks.push(current.join('\n'));
765:       current = [];
766:       len = 0;
767:     }
768:   }
769: 
770:   if (current.length > 0) chunks.push(current.join('\n'));
