const fs = require('fs');

const text = fs.readFileSync('D:/JV/novel yoga/Tom Clancy - 09. Rainbow six - vol. 1+2 (Terjemahan ID-Direct).txt', 'utf8');
const lines = text.split('\n');

const nameMap = {
  'Chavez': 'Ding',
  'John': 'Clark',
  'Al': 'Stanley',
  'Bill': 'Henriksen'
};

const samples = [];
let fixedCount = 0;

for (let i = 0; i < lines.length; i++) {
  let line = lines[i];

  // 1. Cek pola: "Ucapan..." kata/jawab/bisik Si Fulan
  const quoteAfterMatch = line.match(/^"([^"]+)"\s*(?:kata|jawab|tanya|bisik|perintah|seru|timpal|sengit|keluh|balas|sambung|ucap|pikir)\s+([A-Z][a-zA-Z\s.-]{1,20})(.*)$/i);
  if (quoteAfterMatch) {
    let speaker = quoteAfterMatch[2].trim().replace(/\.$/, '');
    const speech = quoteAfterMatch[1];
    const rest = quoteAfterMatch[3] ? quoteAfterMatch[3].trim() : '';

    if (nameMap[speaker]) speaker = nameMap[speaker];

    if (samples.length < 10) {
      samples.push({ before: line, after: `${speaker}: "${speech}"${rest ? ' (' + rest.replace(/^[\s,;]+/, '') + ')' : ''}` });
    }
    fixedCount++;
  }
}

console.log(JSON.stringify({ fixedCount, samples }, null, 2));

