const http = require('http');

const API_URL = 'http://localhost:20128/v1/chat/completions';
const API_KEY = 'sk-2e591994696af18e-71ijj7-14263abd';
const MODEL = 'ag/gemini-3.8-flash';

const prompt = `Terjemahkan kalimat taktis ini ke bahasa Indonesia santai: "Target in sight, moving to breach point."`;

function sendRequest(id) {
  return new Promise((resolve) => {
    const payload = JSON.stringify({
      model: MODEL,
      messages: [{ role: 'user', content: prompt }],
      temperature: 0.6
    });

    const start = Date.now();
    const req = http.request({
      hostname: 'localhost',
      port: 20128,
      path: '/v1/chat/completions',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${API_KEY}`,
        'Content-Length': Buffer.byteLength(payload)
      },
      timeout: 30000
    }, (res) => {
      let data = '';
      res.on('data', c => data += c);
      res.on('end', () => {
        const dur = Date.now() - start;
        if (res.statusCode >= 200 && res.statusCode < 300) {
          resolve({ id, ok: true, status: res.statusCode, dur });
        } else {
          resolve({ id, ok: false, status: res.statusCode, dur, error: data.substring(0, 150) });
        }
      });
    });

    req.on('error', (e) => {
      resolve({ id, ok: false, status: 0, dur: Date.now() - start, error: e.message });
    });
    req.on('timeout', () => {
      req.destroy();
      resolve({ id, ok: false, status: 408, dur: Date.now() - start, error: 'Timeout' });
    });

    req.write(payload);
    req.end();
  });
}

async function testConcurrency(concurrency) {
  console.log(`\n--- Menguji Concurrency ${concurrency} workers ---`);
  const promises = [];
  for (let i = 1; i <= concurrency; i++) {
    promises.push(sendRequest(i));
  }
  const results = await Promise.all(promises);
  const success = results.filter(r => r.ok).length;
  const failed = results.filter(r => !r.ok);
  const avgDur = Math.round(results.filter(r => r.ok).reduce((a, b) => a + b.dur, 0) / (success || 1));

  console.log(`Hasil: ${success}/${concurrency} Berhasil. Rata-rata: ${avgDur}ms.`);
  if (failed.length > 0) {
    console.log(`Gagal ${failed.length} request: Status ${failed[0].status} - ${failed[0].error}`);
    return false;
  }
  return true;
}

async function main() {
  console.log('Target Router: 9router (ag/gemini-3.8-flash)');
  const levels = [3, 5, 8, 10, 15, 20];
  for (const c of levels) {
    const ok = await testConcurrency(c);
    if (!ok) {
      console.log(`\n⚠️ Limit/Kegagalan terdeteksi pada ${c} workers!`);
      break;
    }
    await new Promise(r => setTimeout(r, 1000));
  }
}

main();

