function splitParagraphSafe(txt, maxChars) {
  const paragraphs = txt.split('\n');
  const chunks = [];
  let current = [];
  let len = 0;

  for (const p of paragraphs) {
    current.push(p);
    len += p.length + 1;
    if (len >= maxChars) {
      chunks.push(current.join('\n'));
      current = [];
      len = 0;
    }
  }
  if (current.length > 0) chunks.push(current.join('\n'));
  return chunks;
}

