const fs = require('fs');

const text = fs.readFileSync('D:/JV/novel yoga/A_Game_of_Thrones_A_Song_of_Ice_and_Fire_1 (Terjemahan ID-Direct).txt', 'utf8');

// Cek kata terlarang KBBI kaku
const bannedWords = ['mencicit', 'menukas', 'menimpali', 'tersenyum simpul', 'bergumam', 'meracau', 'tatkala', 'terpendar', 'kendati demikian'];
const foundBanned = {};
bannedWords.forEach(w => {
  const count = (text.match(new RegExp('\\b' + w + '\\b', 'gi')) || []).length;
  if (count > 0) foundBanned[w] = count;
});

// Cek dialog
const lines = text.split('\n');
const nameCounts = {};
let totalDialog = 0;
let quoteOnly = 0;

lines.forEach(l => {
  const t = l.trim();
  const m = t.match(/^([A-Z][a-zA-Z\s.-]{1,30}):\s*["']/);
  if (m) {
    totalDialog++;
    const n = m[1].trim();
    nameCounts[n] = (nameCounts[n] || 0) + 1;
  } else if (/^["']/.test(t)) {
    quoteOnly++;
  }
});

const sorted = Object.entries(nameCounts).sort((a,b) => b[1] - a[1]);
console.log('Banned words found:', foundBanned);
console.log('Total Dialogs with Name:', totalDialog);
console.log('Quotes without Name:', quoteOnly);
console.log('Top Characters:');
console.log(JSON.stringify(sorted.slice(0, 15), null, 2));

